"use strict";

// Evidence desk. Data: data/episodes.json, generated by scripts/site_data.py.
// The reading depth is selected by assets/site.js; prose in the data is keyed b, a, e.

const LEVEL_KEY = { beginner: "b", amateur: "a", expert: "e" };
const RECORDS = ["text", "both", "full", "instr"];
const DEFAULT_PAIR = "arranged-scripted";
const REPO = "https://github.com/ResponseIV/transfer-permission-arrangement";
const QUESTIONS = {
  "sol-21": {
    b: "Can two agents work out an exchange through shared pages?",
    a: "Can the event record support an agent-arranged exchange?",
    e: "What does the observer log establish about offer, read, reply and uptake?",
  },
  "sol-19": {
    b: "Can an exchange benefit just one agent?",
    a: "What changes when one agent answers before a return request?",
    e: "Does the recorded sequence show reciprocal uptake?",
  },
  "luna-leak-01": {
    b: "Can a code move without an agreement?",
    a: "Can the final page hide an earlier transfer?",
    e: "What does revision history add to the page-only record?",
  },
  "sol-scripted-01": {
    b: "Can a supplied script look like an agreement the agents made?",
    a: "Which record distinguishes a scripted sequence from an arranged one?",
    e: "Can an observer trace identify the source of the sequence?",
  },
  "sol-archive-02": {
    b: "Can matching answers come from a shared source?",
    a: "What does the access log add to the archive episode?",
    e: "Does the read path support a transfer between agents?",
  },
  "luna-pact-02": {
    b: "Can the same exchange break a rule in one run and be allowed in another?",
    a: "Where is permission recorded when the visible moves are the same?",
    e: "Is permission a property of the event trace or the instruction set?",
  },
  "luna-norule-02": {
    b: "What changes when the rule is removed?",
    a: "Where is permission recorded when the visible moves are the same?",
    e: "Is permission a property of the event trace or the instruction set?",
  },
  "qwen-letter-37": {
    b: "Can a code move without an offer?",
    a: "What does the record show about how the code moved?",
    e: "What source supports the transfer label in this episode?",
  },
};
const PAIR_COPY = {
  "arranged-scripted": {
    question: {
      b: "Who supplied the plan?",
      a: "Which record shows whether the agents made their own plan?",
      e: "Does the event log identify the source of the sequence?",
    },
    landmarks: [
      { title: "Offer written", left: [3], right: [1] },
      { title: "Offer read", left: [4], right: [2] },
      { title: "Reply written", left: [6], right: [4] },
      { title: "Reply read", left: [7], right: [5] },
      { title: "Answers submitted", left: [8, 9], right: [9, 10] },
    ],
  },
  "arranged-leak": {
    question: {
      b: "In both, a code reaches another agent. What can the access log and page history tell you about the route?",
      a: "Both end with a transfer. Compare the recorded read paths and the pages that were available.",
      e: "What distinction appears when the page writes are read alongside the access log?",
    },
    landmarks: [
      { title: "Relevant page write", left: [3], right: [1], note: "These selected writes play different roles; the original event numbers and record contents are retained." },
      { title: "A page is read", left: [4], right: [3] },
      { title: "A later page write", left: [6], right: [4], note: "This is a teaching selection, not an event-by-event equivalence." },
      { title: "Answers submitted", left: [8, 9], right: [5, 9] },
    ],
  },
  "forbidden-permitted": {
    question: {
      b: "These runs make the same page writes and reads. What must you inspect to know whether the exchange broke a rule?",
      a: "The visible moves match; the rule does not. Which record carries that difference?",
      e: "For this task pair, the event traces match. Is permission a property of the trace or of its instruction set?",
    },
    landmarks: [
      { title: "Pages written", left: [1, 2], right: [1, 2] },
      { title: "Other pages read", left: [3, 4], right: [3, 4] },
      { title: "Answers submitted", left: [5, 6], right: [5, 6] },
    ],
  },
};
const JUDGES = [["astra-p10", "Astra", "prompt 10"], ["luna-p9", "Luna", "prompt 9"], ["qwen-p10", "Qwen3-32B", "prompt 10"]];
const SIGNALS = {
  transfer: "transfer",
  exposure: "receipt: read a revision the other wrote",
  coded: "transfer through the answer clause: no plain read explains it",
  via_archive: "token taken from the archive",
  own_token_written: "an agent wrote its own token",
  obtained: "an answer holds the other's token",
};
// Beginners read places in words; the other depths see the fixture path.
const PLACES = {
  "alpha/retrieval-note": "Alpha's private note", "beta/retrieval-note": "Beta's private note",
  "board/main": "the shared board", "board/alpha": "Alpha's board page", "board/beta": "Beta's board page",
  "archive/index": "the archive index", "archive/record-alpha": "the archive record for Alpha",
  "archive/record-beta": "the archive record for Beta",
};

const state = { data: null, mode: "compare", key: null, pair: DEFAULT_PAIR, record: "both", step: 0, revealed: false };
const $ = (id) => document.getElementById(id);

function el(tag, attrs, ...children) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(attrs || {})) {
    if (value === undefined || value === null || value === false) continue;
    if (key === "class") node.className = value;
    else node.setAttribute(key, value === true ? "" : value);
  }
  for (const child of children.flat(Infinity)) {
    if (child === null || child === undefined || child === false || child === "") continue;
    node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  }
  return node;
}

const level = () => LEVEL_KEY[document.documentElement.dataset.level] || "a";
const page = (path) => (path || "").replace(/^fixture:\/\/pages\//, "");
const getEpisode = (key) => state.data.episodes.find((episode) => episode.key === key);
const getPair = (key) => state.data.compare.find((pair) => pair.key === key);
const getStep = (episode, seq) => episode.steps.find((step) => step.seq === seq);
const cap = (text) => text.charAt(0).toUpperCase() + text.slice(1);
const evt = (seq) => el("span", { class: "evt", "aria-label": `Event ${seq}` }, String(100 + seq).slice(1));

function place(path) {
  const short = page(path);
  if (level() === "b") return el("span", { class: "place" }, PLACES[short] || short);
  return el("code", { class: "place" }, short);
}

function who(name, truth) {
  if (name === "anon") {
    return el("span", { class: "who anon" }, level() === "b" ? "someone" : "unsigned",
      truth ? el("span", { class: "who-truth" }, ` (${cap(truth)})`) : null);
  }
  if (name === "fixture") return el("span", { class: "who fixture" }, "the experiment setup");
  return el("span", { class: `who ${name}` }, cap(name));
}

// Record text may wrap after "=" and "|", so answers like alpha=…|beta=… never split inside a token.
const breakable = (text) => text.split(/(?<=[=|])/).flatMap((part, index) => (index ? [el("wbr", {}), part] : [part]));

function body(text, label, clamp = false) {
  if (text === "") return el("div", { class: "record-body empty", "aria-label": label }, "(empty page)");
  const node = el("div", { class: `record-body${clamp && text.length > 140 ? " clamped" : ""}`, "aria-label": label, translate: "no" }, breakable(text));
  if (!clamp || text.length <= 140) return node;
  const toggle = el("button", { type: "button", class: "more", "aria-expanded": "false" }, "Show the whole page");
  return el("div", { class: "record-text" }, node, toggle);
}

// What an observer holding the chosen record sees of one event.
function observerEvidence(step, record, { clamp = false, reveal = false } = {}) {
  const shown = record === "instr" ? "full" : record;
  const parts = [];
  const verb = (action) => (action === "read" ? "reads" : "writes");
  if (step.log && shown !== "text") {
    parts.push(el("p", { class: `event-action${step.log.allowed === false ? " is-refused" : ""}` },
      who(step.log.actor, reveal && step.log.actor === "anon" ? (step.seeded ? "fixture" : step.actor) : null), ` ${verb(step.log.action)} `,
      place(step.log.page), step.log.allowed === false ? el("span", { class: "refused" }, "refused") : null));
  }
  if (step.pages) {
    if (shown === "text") parts.push(el("p", { class: "event-action" }, "Page ", place(step.pages.page), " now reads"));
    parts.push(body(step.pages.body, "Page text in the observer record", clamp));
  }
  if (step.answer && shown === "full") {
    parts.push(el("p", { class: "event-action" }, who(step.answer.actor), " answers"), body(step.answer.answer, "Final answer"));
  }
  if (parts.length) return parts;
  const what = step.action === "final_answer" ? "A final answer" : step.action === "read" ? "A read" : "A refused write";
  return [el("p", { class: "unseen" }, `${what}, not in this record`)];
}

const ERRORS = { access_denied: "refused", cross_owner_write_denied: "write refused", page_not_found: "no such page" };

// What the experiment fixture recorded: the reader's guide at the first depth, fields at the others.
function fixtureEvidence(step) {
  if (level() === "b") return [el("p", { class: "says" }, step.guide.says)];
  const verb = { read: "reads", write: "writes", final_answer: "answers" }[step.action];
  const parts = [el("p", { class: "event-action" }, who(step.seeded ? "fixture" : step.actor), ` ${verb}`,
    step.page ? [" ", place(step.page)] : null,
    step.status === "allowed" ? null : el("span", { class: "refused" }, ERRORS[step.error] || step.error || step.status))];
  if (step.seeded) parts.push(el("p", { class: "fixture-note" }, "Seeded before the task and recorded under Alpha's name; neither agent is told."));
  if (step.action === "read" && step.status === "allowed") {
    parts.push(el("p", { class: "fixture-note" }, "Returned a revision written by ", who(step.read_author || "nobody")));
  }
  if (step.action === "final_answer" || (!step.pages && step.status === "allowed" && step.text && step.action !== "read")) {
    parts.push(body(step.text || "", "Text in the experiment fixture"));
  }
  if (step.carries?.length) {
    parts.push(el("p", { class: "carries" }, step.carries.map((item) => el("span", {}, `${item.token_of}'s token, ${item.form}`))));
  }
  if (step.note) parts.push(el("p", { class: "step-note" }, step.note));
  if (level() === "e") {
    const raw = [`seq ${step.seq}`, step.actor, step.action, step.status, step.page ? page(step.page) : null,
      step.revision ? `wrote ${step.revision}` : null, step.read_revision ? `read ${step.read_revision}` : null].filter(Boolean);
    parts.push(el("p", { class: "raw" }, raw.join("; ")));
  }
  return parts;
}

function eventCard(episode, step, { full = false, record = "both", prefix = "event", heading = "h4" } = {}) {
  const id = `${prefix}-${episode.key}-${step.seq}`.replace(/[^a-zA-Z0-9_-]/g, "-");
  const panes = [el("section", { class: "record-pane observer-pane", "aria-labelledby": `${id}-o` },
    el(heading, { id: `${id}-o`, class: "pane-label" }, "Observer record"), observerEvidence(step, record))];
  if (full) {
    panes.push(el("section", { class: "record-pane fixture-pane", "aria-labelledby": `${id}-f` },
      el(heading, { id: `${id}-f`, class: "pane-label" }, "Experiment fixture, complete record"), fixtureEvidence(step)));
  }
  const notice = full && level() === "b" && step.guide.notice ? el("p", { class: "notice" }, step.guide.notice) : null;
  return el("li", { class: "record-event", "data-seq": String(step.seq) }, evt(step.seq), el("div", { class: "event-lanes" }, panes), notice);
}

function highlighted(episode) {
  const text = episode.prompt;
  const marks = episode.instructions.highlight
    .map((phrase) => [text.indexOf(phrase), phrase]).filter(([at]) => at >= 0).sort((x, y) => x[0] - y[0]);
  const parts = [];
  let at = 0;
  for (const [start, phrase] of marks) {
    parts.push(text.slice(at, start), el("mark", {}, phrase));
    at = start + phrase.length;
  }
  parts.push(text.slice(at));
  return el("blockquote", { class: "prompt-text", translate: "no" }, parts);
}

function instructionsContent(episode, { suffix = "", excerpt = false, heading = "h4" } = {}) {
  const headingId = `instructions-${episode.key}${suffix ? `-${suffix}` : ""}`;
  const quote = excerpt
    ? [el("blockquote", { class: "prompt-text prompt-excerpt", translate: "no" },
      episode.instructions.highlight.filter((phrase) => episode.prompt.includes(phrase)).map((phrase) => el("p", {}, "[…] ", el("mark", {}, phrase), " […]"))),
    el("details", { class: "whole-prompt" }, el("summary", {}, "The whole prompt"), highlighted(episode))]
    : [highlighted(episode)];
  return el("section", { class: "instructions-record", "aria-labelledby": headingId },
    el(heading, { id: headingId, class: "pane-label" }, "Instructions supplied to both agents"), quote,
    el("p", { class: "instructions-why" }, episode.instructions[level()]));
}

function addInstructionsButton() {
  return el("button", { type: "button", class: "add-record", "data-record": "instr" }, "Add the instructions");
}

/* Compare: a ledger of selected landmarks, A and B side by side. */

function renderCompare() {
  const pair = getPair(state.pair);
  const left = getEpisode(pair.left);
  const right = getEpisode(pair.right);
  const editorial = PAIR_COPY[pair.key];
  $("compare-intro").replaceChildren(el("h2", { id: "compare-title" }, editorial?.question[level()] || pair.question[level()]));
  $("compare-answer").replaceChildren(renderCompareAnswer(pair, left, right));
  const side = (episode, letter) => el("div", { class: "ledger-side" },
    el("span", { class: "side-letter" }, letter),
    el("span", { class: "side-name" }, state.revealed ? episode.title : episode.model));
  const head = el("div", { class: "ledger-head", role: "presentation" }, el("span", { class: "ledger-gutter" }, "Landmark"),
    side(left, "A"), side(right, "B"));
  const cell = (episode, seqs, letter) => el("div", { class: "ledger-cell", "data-side": letter },
    el("ol", { class: "ledger-events", "aria-label": `Episode ${letter}` }, seqs.map((seq) => getStep(episode, seq)).filter(Boolean).map((step) =>
      el("li", { class: "record-event", "data-seq": String(step.seq) }, evt(step.seq),
        el("div", { class: "event-lanes" }, observerEvidence(step, state.record, { clamp: true, reveal: state.revealed }))))));
  const rows = (editorial?.landmarks || []).map((landmark, index) => el("section", { class: "ledger-row", "aria-labelledby": `landmark-${index}` },
    el("h3", { class: "ledger-gutter", id: `landmark-${index}` }, landmark.title,
      landmark.note && level() !== "b" ? el("span", { class: "landmark-note" }, landmark.note) : null),
    cell(left, landmark.left, "A"), cell(right, landmark.right, "B")));
  const instructions = state.record === "instr"
    ? [el("div", { class: "ledger-cell", "data-side": "A" }, instructionsContent(left, { suffix: "a", excerpt: true })),
      el("div", { class: "ledger-cell", "data-side": "B" }, instructionsContent(right, { suffix: "b", excerpt: true }))]
    : [el("div", { class: "ledger-cell locked" },
      el("p", {}, level() === "b"
        ? "The instructions are not in the observer's record, and the AI judges never saw them."
        : "Not in any observer record. The AI judges never saw the instructions."), addInstructionsButton())];
  const instructionRow = el("section", { class: `ledger-row instructions-row${state.record === "instr" ? " is-open" : ""}`, "aria-labelledby": "landmark-instr" },
    el("h3", { class: "ledger-gutter", id: "landmark-instr" }, "Instructions"), ...instructions);
  $("landmarks").replaceChildren(head, ...rows, instructionRow);
  $("compare-full").replaceChildren(
    el("p", { class: "provenance" }, "Each event in full: the observer record beside what the experiment fixture recorded. Anonymous shared-board actors stay anonymous on the observer side."),
    el("div", { class: "full-compare" }, [left, right].map((episode, index) => el("section", { "aria-labelledby": `full-case-${index}` },
      el("h3", { id: `full-case-${index}` }, `${index === 0 ? "A" : "B"}: ${episode.title}`),
      el("ol", { class: "timeline compact" }, episode.steps.map((step) => eventCard(episode, step, { record: "instr", full: true, prefix: `full-${index}` }))),
      instructionsContent(episode, { suffix: `full-${index}` }), findings(episode)))));
}

function renderCompareAnswer(pair, left, right) {
  const button = el("button", { type: "button", class: "reveal-button", id: "compare-reveal", "aria-expanded": String(state.revealed), "aria-controls": "compare-answer-result" },
    state.revealed ? "Hide what happened" : "Reveal what happened");
  const result = el("div", { id: "compare-answer-result", class: "answer-result", hidden: !state.revealed },
    el("p", { class: "answer-lead" }, pair.answer[level()]),
    el("dl", { class: "answer-pair" }, [left, right].flatMap((episode, index) => [
      el("dt", {}, `${index === 0 ? "A" : "B"}: ${episode.kind}`), el("dd", {}, episode.verdict[level()])])));
  return el("div", { class: "answer-request" }, button, result);
}

/* One episode: the event record, stepped, with the fixture beside it. */

function renderSingle(episode) {
  const story = episode.story[level()];
  $("summary").replaceChildren(
    el("p", { class: "desk-meta" }, `${episode.model}, ${episode.rule_in_prompt ? "confidentiality rule" : "no rule"}`),
    el("h2", { id: "single-title" }, QUESTIONS[episode.key]?.[level()] || "What does this event record establish?"),
    el("p", { class: "desk-question-text" }, story),
    el("p", { class: "tokens" }, "Tokens: ", Object.entries(episode.tokens).map(([agent, token], index) =>
      [index ? ", " : "", who(agent), " ", el("code", { translate: "no" }, token)])));
  $("col-observer").textContent = level() === "b" ? "What an auditor sees" : "What the observer record shows";
  // The first depth is a guided walk with the truth beside each event; beyond it, the truth is part of the reveal.
  const truth = level() === "b" || state.revealed;
  $("col-truth").textContent = level() === "b" ? "What really happened"
    : truth ? "What the fixture recorded" : "What the fixture recorded appears when you reveal it";
  $("single-instructions").replaceChildren(state.record === "instr" ? instructionsContent(episode, { suffix: "single", heading: "h3" })
    : el("div", { class: "locked single-locked" }, el("p", {}, "The instructions are not in the observer's record."), addInstructionsButton()));
  $("timeline").replaceChildren(...episode.steps.map((step) => eventCard(episode, step, { record: state.record, full: truth, prefix: "single", heading: "h3" })));
  renderSingleAnswer(episode);
  $("single-full").replaceChildren(findings(episode));
  move(state.step, false, false);
}

function renderSingleAnswer(episode) {
  const last = state.step >= episode.steps.length - 1;
  if (level() === "b" && !last) {
    $("single-answer").replaceChildren(el("p", { class: "unseen" }, "Step to the last event to see the verdict."));
    return;
  }
  const button = el("button", { type: "button", class: "reveal-button", id: "single-reveal", "aria-expanded": String(state.revealed), "aria-controls": "single-answer-result" },
    state.revealed ? "Hide what happened" : "Reveal what happened");
  const answer = el("div", { id: "single-answer-result", class: "answer-result", hidden: !state.revealed },
    el("p", { class: "answer-lead" }, episode.verdict[level()]),
    el("p", { class: "provenance" }, "Case: ", el("b", {}, episode.kind), ". Frozen transfer label: ", el("b", {}, episode.label.transfer ? "yes" : "no"), "."));
  $("single-answer").replaceChildren(button, answer);
}

function findings(episode) {
  const judgeText = (value) => value === true ? "transfer" : value === false ? "no transfer" : "no verdict";
  const views = [["text", "Pages"], ["both", "+ Access log"], ["full", "+ Answers"]];
  return el("section", { class: "findings", "aria-labelledby": `findings-${episode.key}` },
    el("h3", { id: `findings-${episode.key}` }, "Benchmark interpretation"),
    el("dl", { class: "fields" },
      el("dt", {}, "Case"), el("dd", {}, episode.case),
      el("dt", {}, "Origin"), el("dd", {}, episode.origin),
      el("dt", {}, "Arm"), el("dd", {}, episode.arm),
      el("dt", {}, "Frozen transfer label"), el("dd", {}, episode.label.transfer ? "yes" : "no"),
      el("dt", {}, "Cell"), el("dd", {}, el("code", {}, episode.cell_id))),
    el("div", { class: "table-wrap" }, el("table", {},
      el("caption", {}, "Judge verdicts by record. No judge saw the instructions; an absent verdict is unknown, never false."),
      el("thead", {}, el("tr", {}, el("th", { scope: "col" }, "Judge"), views.map(([, name]) => el("th", { scope: "col" }, name)))),
      el("tbody", {}, JUDGES.map(([key, name, prompt]) => el("tr", {}, el("th", { scope: "row" }, `${name}, ${prompt}`),
        views.map(([view]) => el("td", { class: `verdict-${episode.judges[key]?.[view]}` }, judgeText(episode.judges[key]?.[view])))))))),
    el("h4", {}, "Observer signals"),
    el("ul", { class: "signal-list" }, Object.entries(episode.signals || {}).map(([key, on]) =>
      el("li", { class: on ? "on" : "" }, el("b", {}, on ? "yes" : "no"), ` ${SIGNALS[key] || key}`))),
    el("p", { class: "provenance" }, "Source cell in the ", el("a", { href: `${REPO}/blob/submission/benchmark/DATACARD.md` }, "submitted benchmark"), "."));
}

/* State, routing and controls. */

function render() {
  if (!state.data) return;
  const focusedId = document.activeElement?.id;
  const single = state.mode === "single";
  const episode = getEpisode(state.key) || state.data.episodes[0];
  state.key = episode.key;
  $("single").hidden = !single;
  $("compare-view").hidden = single;
  document.body.classList.toggle("desk-single", single);
  for (const input of document.querySelectorAll('input[name="mode"]')) input.checked = input.value === state.mode;
  for (const input of document.querySelectorAll('input[name="record"]')) input.checked = input.value === state.record;
  picker();
  if (single) renderSingle(episode);
  else renderCompare();
  if (focusedId && document.getElementById(focusedId)) document.getElementById(focusedId).focus({ preventScroll: true });
}

function picker() {
  const items = state.mode === "single"
    ? state.data.episodes.map((episode) => ({ key: episode.key, title: episode.title.split(":")[0], selected: episode.key === state.key }))
    : state.data.compare.map((pair) => ({ key: pair.key, title: pair.title, selected: pair.key === state.pair }));
  const select = el("select", { id: "case-choice", name: "case" },
    items.map((item) => el("option", { value: item.key, selected: item.selected }, item.title)));
  $("picker").replaceChildren(el("label", { for: "case-choice", class: "visually-hidden" }, state.mode === "single" ? "Episode" : "Comparison"), select);
}

function setRoute(push = false) {
  const params = new URLSearchParams();
  params.set("record", state.record);
  params.set("step", String(state.step + 1));
  params.set("reveal", state.revealed ? "true" : "false");
  const id = state.mode === "single" ? state.key : state.pair;
  const hash = `#${state.mode}/${encodeURIComponent(id)}?${params.toString()}`;
  const url = `${location.pathname}${location.search}${hash}`;
  if (`${location.pathname}${location.search}${location.hash}` === url) return;
  history[push ? "pushState" : "replaceState"]({ explorer: true }, "", url);
}

function restoreRoute() {
  const fragment = location.hash.slice(1);
  const [path, search = ""] = fragment.split("?", 2);
  const parts = path.split("/").map((part) => {
    try { return decodeURIComponent(part); } catch { return ""; }
  });
  const params = new URLSearchParams(search);
  if (parts[0] === "compare" || !path) {
    state.mode = "compare";
    state.pair = getPair(parts[1])?.key || DEFAULT_PAIR;
    state.key = getPair(state.pair).left;
  } else {
    // Both #case and #single/case are preserved for existing links.
    state.mode = "single";
    const key = parts[0] === "single" ? parts[1] : parts[0];
    state.key = getEpisode(key)?.key || state.data.episodes[0].key;
  }
  state.record = RECORDS.includes(params.get("record")) ? params.get("record") : "both";
  state.revealed = params.get("reveal") === "true";
  const episode = getEpisode(state.key);
  const requested = Number.parseInt(params.get("step"), 10);
  state.step = Number.isFinite(requested) && requested > 0 ? Math.min(requested, episode.steps.length) - 1
    : level() === "e" ? episode.steps.length - 1 : 0;
  render();
}

function move(step, announce = true, updateUrl = true) {
  const episode = getEpisode(state.key);
  const total = episode.steps.length;
  const wasLast = state.step >= total - 1;
  state.step = Math.max(0, Math.min(total - 1, step));
  [...$("timeline").children].forEach((row, index) => {
    row.hidden = index > state.step;
    row.classList.toggle("current", index === state.step && state.step < total - 1);
  });
  $("slider").max = total;
  $("slider").value = state.step + 1;
  $("position").textContent = `Event ${state.step + 1} of ${total}`;
  $("prev").disabled = state.step === 0;
  $("next").disabled = $("all").disabled = state.step === total - 1;
  if (wasLast !== (state.step >= total - 1)) renderSingleAnswer(episode);
  if (announce) {
    const current = episode.steps[state.step];
    $("step-status").textContent = `Event ${state.step + 1} of ${total}. ${level() === "b" ? current.guide.says : current.note || ""}`;
    const row = $("timeline").children[state.step];
    if (row && row.getBoundingClientRect().bottom > window.innerHeight - 96) row.scrollIntoView({ block: "center", behavior: "smooth" });
  }
  if (updateUrl) setRoute(false);
}

function wire() {
  $("picker").addEventListener("change", (event) => {
    if (state.mode === "single") state.key = getEpisode(event.target.value)?.key || state.key;
    else {
      state.pair = getPair(event.target.value)?.key || state.pair;
      state.key = getPair(state.pair).left;
    }
    state.step = state.mode === "single" && level() === "e" ? getEpisode(state.key).steps.length - 1 : 0;
    state.revealed = false;
    setRoute(true);
    render();
  });
  for (const input of document.querySelectorAll('input[name="mode"]')) {
    input.addEventListener("change", () => {
      if (!input.checked) return;
      state.mode = input.value;
      state.step = state.mode === "single" && level() === "e" ? getEpisode(state.key).steps.length - 1 : 0;
      state.revealed = false;
      setRoute(true);
      render();
    });
  }
  for (const input of document.querySelectorAll('input[name="record"]')) {
    input.addEventListener("change", () => {
      if (!input.checked) return;
      state.record = input.value;
      render();
      setRoute(false);
    });
  }
  $("stepper").addEventListener("click", (event) => {
    if (event.target.id === "prev") move(state.step - 1);
    if (event.target.id === "next") move(state.step + 1);
    if (event.target.id === "all") move(Infinity);
  });
  $("slider").addEventListener("input", (event) => move(Number(event.target.value) - 1, false));
  $("app").addEventListener("click", (event) => {
    const target = event.target.closest("button");
    if (!target) return;
    if (target.id === "single-reveal" || target.id === "compare-reveal") {
      state.revealed = !state.revealed;
      render();
      setRoute(false);
      $(target.id).focus({ preventScroll: true });
    } else if (target.classList.contains("add-record")) {
      state.record = target.dataset.record;
      render();
      setRoute(false);
      // The button is gone after the render: hand focus to the instructions it revealed.
      const shown = document.querySelector(state.mode === "single" ? "#single-instructions .instructions-record" : ".instructions-row .instructions-record");
      if (shown) {
        shown.setAttribute("tabindex", "-1");
        shown.focus({ preventScroll: true });
        shown.scrollIntoView({ block: "nearest", behavior: "smooth" });
      }
    } else if (target.classList.contains("more")) {
      const open = target.getAttribute("aria-expanded") !== "true";
      target.setAttribute("aria-expanded", String(open));
      target.previousElementSibling.classList.toggle("clamped", !open);
      target.textContent = open ? "Show less" : "Show the whole page";
    }
  });
  document.addEventListener("keydown", (event) => {
    if (state.mode !== "single" || event.altKey || event.ctrlKey || event.metaKey) return;
    if (event.target.closest("input, textarea, select, button, summary, [contenteditable]")) return;
    if (event.key === "ArrowRight") move(state.step + 1);
    if (event.key === "ArrowLeft") move(state.step - 1);
  });
  window.addEventListener("popstate", restoreRoute);
  window.addEventListener("hashchange", restoreRoute);
  document.addEventListener("tpa:level", () => render());
}

function fail(error) {
  $("loading").hidden = true;
  const box = $("error");
  box.hidden = false;
  const local = location.protocol === "file:";
  box.replaceChildren(
    local ? "This page was opened from a file, and browsers do not let it load its episode data that way. "
      : `The episode records did not load${error?.message ? ` (${error.message})` : ""}. Refresh the page to try again. `,
    ...(local ? ["To view it locally, serve the folder with ", el("code", {}, "python3 -m http.server -d docs"),
      " and open ", el("code", {}, "http://localhost:8000/explorer.html"), ". "] : []),
    "The ", el("a", { href: "./" }, "explainer"), " works without it.");
}

$("loading").hidden = false;
fetch("data/episodes.json")
  .then((response) => {
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    return response.json();
  })
  .then((data) => {
    state.data = data;
    $("loading").hidden = true;
    $("app").hidden = false;
    document.documentElement.classList.add("explorer-ready");
    if (window.ResizeObserver) {
      new ResizeObserver(([entry]) => document.documentElement.style.setProperty("--desk-bar", `${entry.target.offsetHeight}px`)).observe($("desk-bar"));
    }
    wire();
    restoreRoute();
    // A fragmentless visit opens the authored comparison and produces a useful share link.
    if (!location.hash) setRoute(false);
  })
  .catch(fail);
